const hamsterSkins=[{id:'classic',name:'Классический',price:0},{id:'chibis',name:'Чибис',price:0,path:'chibis.jpeg'},{id:'siply',name:'Сиплый',price:0,path:'siply.jpeg'},{id:'basmach',name:'Басмач',price:0,path:'basmach.jpeg'},{id:'sych',name:'Сыч',price:0,path:'sych.jpeg'},{id:'shershavy',name:'Шершавый',price:0,path:'shershavy.jpeg'}];
