const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',schedule:'<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M8 2v4M16 2v4M3 10h18M8 14h.01M12 14h.01M16 14h.01"/>',tasks:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-8"/>',study:'<path d="m2 10 10-6 10 6-10 6zM6 13v5c4 3 8 3 12 0v-5M22 10v7"/>',calendar:'<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M8 2v4M16 2v4M3 10h18M7 15h4v4H7z"/>',back:'<path d="m15 18-6-6 6-6"/>',chevron:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',cloud:'<path d="M20 17a4 4 0 0 0-1-7.9A7 7 0 0 0 5 11a4 4 0 0 0 0 8h14"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4.2 21v-2a7.8 7.8 0 0 1 15.6 0v2"/>' ,profile:'<circle cx="12" cy="7" r="4"/><path d="M4.2 21v-2a7.8 7.8 0 0 1 15.6 0v2"/>',check:'<path d="m4 12 5 5L20 6"/>',book:'<path d="M4 4h12a3 3 0 0 1 3 3v13H7a3 3 0 0 1-3-3zM7 4v16"/>',chart:'<path d="M4 20V4M4 20h17M8 15l4-4 4 2 4-7"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',trash:'<path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14M10 11v7m4-7v7"/>'};
const I=(name,size)=>`<svg class="icon" ${size?`style="width:${size}px;height:${size}px"`:''} viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,add=(d,n)=>{let v=new Date(d);v.setDate(v.getDate()+n);return v},minutes=t=>{let [h,m]=String(t||'0:0').split(':').map(Number);return h*60+m},today=()=>new Date();
// Existing schedule uses parity 0 for numerator. Anchor: 2026-11-11 was numerator.
const parity=d=>((Math.floor((new Date(d.getFullYear(),d.getMonth(),d.getDate(),12)-new Date(2026,10,9,12))/604800000)%2)+2)%2;
const parityName=d=>(ui.week??parity(d))===0?'Числитель · ЧС':'Знаменатель · ЗН';
const lessons=d=>{const wd=d.getDay(),p=ui.week??parity(d);let arr=(seed.schedule[wd]||{})[p]||[];const extra=customLessons.filter(x=>x.day===wd&&x.parity===p);return [...arr,...extra].map((x,i)=>{let c=x.id?null:data.changes.find(z=>z.date===dateISO(d)&&Number(z.index)===i);return c?.mode==='cancel'?null:c?.mode==='move'?{...x,start:c.start||x.start,end:c.end||x.end,room:c.room||x.room,building:c.building||x.building}:x}).filter(Boolean).sort((a,b)=>minutes(a.start)-minutes(b.start))};
const activeLesson=()=>{let d=today(),n=d.getHours()*60+d.getMinutes(),arr=lessons(d),current=arr.find(l=>minutes(l.start)<=n&&n<minutes(l.end)),next=arr.find(l=>minutes(l.start)>n);return {current,next,lesson:current||next,n}};
const done=t=>['Готово','Сдано','Принято'].includes(t.status),total=k=>data.scores.filter(s=>s.sub===k).reduce((n,s)=>n+(Number(s.value)||0),0);
